-- NONNUMBERED prepared sale after24candidates; offline only.
BEGIN;
SELECT alert_cron.lock_source();
DO $admission$ DECLARE fingerprint text;BEGIN
 IF current_user<>'postgres' THEN RAISE EXCEPTION 'Reviewed sale installation owner required';END IF;
 SELECT baseline INTO fingerprint FROM (SELECT md5(jsonb_agg(jsonb_build_object(
 'view',CASE WHEN c.relkind='v' THEN pg_get_viewdef(c.oid) ELSE NULL END,'table',c.relname,'kind',c.relkind,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,
 'acl',(SELECT jsonb_agg(jsonb_build_array(CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,pg_get_userbyid(x.grantor),x.privilege_type,x.is_grantable) ORDER BY CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,pg_get_userbyid(x.grantor),x.privilege_type,x.is_grantable) FROM aclexplode(coalesce(c.relacl,acldefault('r',c.relowner)))x),
 'columns',(SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'required',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'default',pg_get_expr(d.adbin,d.adrelid),'collation',CASE WHEN a.attcollation=0 THEN NULL ELSE (SELECT n.nspname||'.'||co.collname FROM pg_collation co JOIN pg_namespace n ON n.oid=co.collnamespace WHERE co.oid=a.attcollation) END,'acl',(SELECT jsonb_agg(jsonb_build_array(CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,pg_get_userbyid(x.grantor),x.privilege_type,x.is_grantable) ORDER BY CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,pg_get_userbyid(x.grantor),x.privilege_type,x.is_grantable) FROM aclexplode(a.attacl)x)) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),
 'constraints',(SELECT jsonb_agg(jsonb_build_array(x.conname,pg_get_constraintdef(x.oid),x.convalidated,x.condeferrable,x.condeferred) ORDER BY x.conname) FROM pg_constraint x WHERE x.conrelid=c.oid),
 'indexes',(SELECT jsonb_agg(jsonb_build_array(pg_get_indexdef(i.indexrelid),i.indisvalid,i.indisready,i.indislive,i.indimmediate,i.indnullsnotdistinct) ORDER BY pg_get_indexdef(i.indexrelid)) FROM pg_index i WHERE i.indrelid=c.oid),
 'policies',(SELECT jsonb_agg(to_jsonb(p) ORDER BY p.policyname) FROM pg_policies p WHERE p.schemaname='public' AND p.tablename=c.relname),
 'triggers',(SELECT jsonb_agg(jsonb_build_array(pg_get_triggerdef(t.oid),t.tgenabled,t.tgtype,t.tgdeferrable,t.tginitdeferred,md5(f.prosrc),pg_get_userbyid(f.proowner),f.prosecdef,f.proconfig) ORDER BY t.tgname) FROM pg_trigger t JOIN pg_proc f ON f.oid=t.tgfoid WHERE t.tgrelid=c.oid AND NOT t.tgisinternal),
 'inherits',(SELECT count(*) FROM pg_inherits WHERE inhrelid=c.oid OR inhparent=c.oid),
 'rules',(SELECT count(*) FROM pg_rewrite WHERE ev_class=c.oid)
) ORDER BY c.relname)::text) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
WHERE n.nspname='public' AND c.relname IN('fin_categorias_gastos','fin_categorias_ingresos','fin_compradores','fin_conceptos_gastos','fin_gastos','fin_ingresos','fin_medios_pago','fin_negocios','fin_parametros','fin_presupuestos','fin_proveedores','fin_regiones','fin_transacciones_ganado','hato_alertas','hato_alertas_config','hato_animales','hato_chequeo_vacas','hato_chequeos','hato_config','hato_eventos','hato_produccion_quincenal','hato_tratamiento_pasos','hato_tratamientos','telegram_alertas_suscripciones','telegram_usuarios','usuarios','v_hato_estado_actual')) AS e(baseline);
 IF fingerprint IS DISTINCT FROM '69463f3ecb18f1ffee565aafda0bb50b' THEN RAISE EXCEPTION 'Unreviewed sale source graph';END IF;
 PERFORM clinical_step_confirmation.assert_retired_writers();PERFORM correction_audit_integrity.assert_boundary();
 IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure('hato_death.snapshot(uuid)') AND md5(p.prosrc)='a6bf1457f7ab6b1adf5cae9c9c78d308' AND NOT p.prosecdef AND p.proconfig=ARRAY['search_path=pg_catalog'] AND pg_get_userbyid(p.proowner)='postgres') OR EXISTS(SELECT 1 FROM (VALUES('anon'),('authenticated'),('service_role'))v(role) WHERE has_function_privilege(v.role,'hato_death.snapshot(uuid)','EXECUTE')) THEN RAISE EXCEPTION 'Unreviewed sale snapshot helper';END IF;
END $admission$;
CREATE SCHEMA hato_sale;
REVOKE ALL ON SCHEMA hato_sale FROM PUBLIC,anon,authenticated,service_role;
CREATE TABLE hato_sale.requests(request_key uuid PRIMARY KEY,owner_id uuid NOT NULL,intent jsonb,original jsonb,plan jsonb,state text NOT NULL CHECK(state IN('pending','committed','canceled')),receipt jsonb,CHECK((state='committed')=(receipt IS NOT NULL)),CHECK(state='canceled' OR intent IS NOT NULL AND original IS NOT NULL AND plan IS NOT NULL));
CREATE TABLE hato_sale.audit(request_key uuid PRIMARY KEY REFERENCES hato_sale.requests(request_key),receipt jsonb NOT NULL);
ALTER TABLE hato_sale.requests ENABLE ROW LEVEL SECURITY;ALTER TABLE hato_sale.audit ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON ALL TABLES IN SCHEMA hato_sale FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION hato_sale.immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN IF TG_OP IN('DELETE','TRUNCATE') OR TG_TABLE_NAME='audit' OR OLD.state<>'pending' OR NEW.state NOT IN('committed','canceled') OR(to_jsonb(NEW)-'state'-'receipt') IS DISTINCT FROM(to_jsonb(OLD)-'state'-'receipt') THEN RAISE EXCEPTION 'Immutable original sale proof';END IF;RETURN NEW;END $$;
CREATE TRIGGER immutable_sale_request BEFORE UPDATE OR DELETE ON hato_sale.requests FOR EACH ROW EXECUTE FUNCTION hato_sale.immutable();
CREATE TRIGGER immutable_sale_audit BEFORE UPDATE OR DELETE ON hato_sale.audit FOR EACH ROW EXECUTE FUNCTION hato_sale.immutable();
CREATE TRIGGER no_truncate_sale_request BEFORE TRUNCATE ON hato_sale.requests FOR EACH STATEMENT EXECUTE FUNCTION hato_sale.immutable();
CREATE TRIGGER no_truncate_sale_audit BEFORE TRUNCATE ON hato_sale.audit FOR EACH STATEMENT EXECUTE FUNCTION hato_sale.immutable();
CREATE FUNCTION hato_sale.actor() RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN PERFORM 1 FROM public.usuarios WHERE id=auth.uid() AND activo IS TRUE AND rol='Gerencia' FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'Fresh active Gerencia sale owner required' USING ERRCODE='42501';END IF;RETURN jsonb_build_object('origin','web','profileId',auth.uid());END $$;
CREATE FUNCTION hato_sale.lock_source() RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE t record;
BEGIN PERFORM alert_cron.lock_source();FOR t IN SELECT tablename FROM pg_tables WHERE schemaname='public' AND tablename IN('fin_categorias_gastos','fin_categorias_ingresos','fin_compradores','fin_conceptos_gastos','fin_gastos','fin_ingresos','fin_medios_pago','fin_negocios','fin_parametros','fin_presupuestos','fin_proveedores','fin_regiones','fin_transacciones_ganado','hato_produccion_quincenal') ORDER BY tablename LOOP EXECUTE format('LOCK TABLE public.%I IN SHARE ROW EXCLUSIVE MODE',t.tablename);END LOOP;END $$;
CREATE FUNCTION hato_sale.finance() RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE t record;value jsonb;result jsonb='{}';
BEGIN FOR t IN SELECT tablename FROM pg_tables WHERE schemaname='public' AND tablename IN('fin_categorias_gastos','fin_categorias_ingresos','fin_compradores','fin_conceptos_gastos','fin_gastos','fin_ingresos','fin_medios_pago','fin_negocios','fin_parametros','fin_presupuestos','fin_proveedores','fin_regiones','fin_transacciones_ganado','hato_produccion_quincenal') ORDER BY tablename LOOP EXECUTE format('SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),''[]'') FROM public.%I x',t.tablename) INTO value;result=result||jsonb_build_object('public.'||t.tablename,value);END LOOP;RETURN result;END $$;
CREATE FUNCTION hato_sale.snapshot(p jsonb) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE negocio public.fin_negocios;categoria public.fin_categorias_ingresos;region public.fin_regiones;medio public.fin_medios_pago;comprador public.fin_compradores;targets jsonb;
BEGIN
 IF(SELECT count(*) FROM public.fin_negocios WHERE nombre='Hato Lechero' AND activo IS TRUE)<>1 THEN RAISE EXCEPTION 'Unambiguous active Hato business required';END IF;
 SELECT * INTO negocio FROM public.fin_negocios WHERE nombre='Hato Lechero' AND activo IS TRUE;
 IF(SELECT count(*) FROM public.fin_categorias_ingresos WHERE negocio_id=negocio.id AND activo IS TRUE AND nombre ILIKE CASE WHEN p->>'tipo'='terneros' THEN '%ternero%' ELSE '%descarte%' END)<>1 THEN RAISE EXCEPTION 'Unambiguous active sale category required';END IF;
 SELECT * INTO categoria FROM public.fin_categorias_ingresos WHERE negocio_id=negocio.id AND activo IS TRUE AND nombre ILIKE CASE WHEN p->>'tipo'='terneros' THEN '%ternero%' ELSE '%descarte%' END;
 SELECT * INTO region FROM public.fin_regiones WHERE id=(p->>'regionId')::uuid AND activo IS TRUE;IF NOT FOUND THEN RAISE EXCEPTION 'Active region required';END IF;
 SELECT * INTO medio FROM public.fin_medios_pago WHERE id=(p->>'medioPagoId')::uuid AND activo IS TRUE;IF NOT FOUND THEN RAISE EXCEPTION 'Active payment required';END IF;
 IF p->>'compradorId' IS NOT NULL THEN SELECT * INTO comprador FROM public.fin_compradores WHERE id=(p->>'compradorId')::uuid AND activo IS TRUE;IF NOT FOUND THEN RAISE EXCEPTION 'Active buyer required';END IF;END IF;
 SELECT coalesce(jsonb_agg(hato_death.snapshot((x->>'id')::uuid) ORDER BY x->>'id'),'[]') INTO targets FROM jsonb_array_elements(p->'animals')x;
 RETURN jsonb_build_object('animals',targets,'refs',jsonb_build_object('negocio',to_jsonb(negocio),'categoria',to_jsonb(categoria),'region',to_jsonb(region),'medio',to_jsonb(medio),'comprador',CASE WHEN comprador.id IS NULL THEN NULL ELSE to_jsonb(comprador) END));
END $$;
CREATE FUNCTION hato_sale.result(r hato_sale.requests) RETURNS jsonb LANGUAGE sql SET search_path=pg_catalog AS $$ SELECT jsonb_build_object('version',1,'requestKey',r.request_key,'owner',r.owner_id,'state',r.state,'intent',r.intent,'original',r.original,'plan',r.plan,'receipt',r.receipt);$$;
CREATE FUNCTION public.fn_hato_sale_web(p_action text,p_request_key uuid,p_intent jsonb,p_expected_owner uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE actor jsonb;r hato_sale.requests;expected hato_sale.requests;original jsonb;after_value jsonb;expected_after jsonb;before_source jsonb;expected_source jsonb;before_finance jsonb;expected_finance jsonb;view_inputs jsonb;
 income public.fin_ingresos;actual_income public.fin_ingresos;e public.hato_eventos;actual_event public.hato_eventos;a public.hato_animales;actual_animal public.hato_animales;correction public.hato_correcciones;corrections jsonb;new_corrections jsonb='[]';targets jsonb='[]';g jsonb;item jsonb;day date;heads integer;amount numeric;new_receipt jsonb;written_audit jsonb;
BEGIN
 IF p_expected_owner IS NULL OR auth.uid() IS DISTINCT FROM p_expected_owner OR p_request_key IS NULL THEN RAISE EXCEPTION 'Original sale owner/key required' USING ERRCODE='42501';END IF;
 actor=hato_sale.actor();IF p_action IS NULL OR p_action NOT IN('prepare','post','status','resolve') THEN RAISE EXCEPTION 'Invalid sale action';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('hato-sale:'||p_request_key::text,0));SELECT * INTO r FROM hato_sale.requests WHERE request_key=p_request_key FOR UPDATE;
 IF FOUND AND r.owner_id IS DISTINCT FROM p_expected_owner THEN RAISE EXCEPTION 'Original sale owner changed' USING ERRCODE='42501';END IF;
 IF p_action<>'prepare' AND p_intent IS NOT NULL THEN RAISE EXCEPTION 'Original sale intent cannot change';END IF;
 IF p_action='status' THEN IF r.request_key IS NULL THEN RETURN jsonb_build_object('version',1,'requestKey',p_request_key,'owner',p_expected_owner,'state','unknown','intent',NULL,'original',NULL,'plan',NULL,'receipt',NULL);END IF;IF r.state='committed' AND NOT EXISTS(SELECT 1 FROM hato_sale.audit WHERE request_key=p_request_key AND receipt=r.receipt) THEN RAISE EXCEPTION 'Original sale audit missing';END IF;RETURN hato_sale.result(r);END IF;
 PERFORM hato_sale.lock_source();before_source=alert_cron.source();expected_source=before_source;before_finance=hato_sale.finance();expected_finance=before_finance;
 view_inputs=jsonb_build_object('checks',(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY id),'[]') FROM public.hato_chequeo_vacas x),'headers',(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY id),'[]') FROM public.hato_chequeos x));
 IF p_action='prepare' THEN
  IF jsonb_typeof(p_intent) IS DISTINCT FROM 'object' OR (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(p_intent)k) IS DISTINCT FROM ARRAY['animals','cabezas','compradorId','fecha','medioPagoId','nombre','refs','regionId','tipo','valor','version'] OR p_intent->'version' IS DISTINCT FROM '1'::jsonb OR jsonb_typeof(p_intent->'tipo') IS DISTINCT FROM 'string' OR jsonb_typeof(p_intent->'fecha') IS DISTINCT FROM 'string' OR jsonb_typeof(p_intent->'regionId') IS DISTINCT FROM 'string' OR jsonb_typeof(p_intent->'medioPagoId') IS DISTINCT FROM 'string' OR jsonb_typeof(p_intent->'compradorId') NOT IN('null','string') OR p_intent->>'tipo' NOT IN('terneros','descarte') OR jsonb_typeof(p_intent->'valor') IS DISTINCT FROM 'string' OR p_intent->>'valor' !~ '^[1-9][0-9]{0,15}$' OR (p_intent->>'valor')::numeric>9007199254740991 OR jsonb_typeof(p_intent->'cabezas') IS DISTINCT FROM 'number' OR jsonb_typeof(p_intent->'nombre') IS DISTINCT FROM 'string' OR length(p_intent->>'nombre')>4000 OR btrim(p_intent->>'nombre') IS DISTINCT FROM p_intent->>'nombre' OR jsonb_typeof(p_intent->'animals') IS DISTINCT FROM 'array' OR jsonb_array_length(p_intent->'animals')>50 THEN RAISE EXCEPTION 'Exact bounded sale intent required';END IF;
  IF ((p_intent->>'regionId')::uuid)::text IS DISTINCT FROM p_intent->>'regionId' OR ((p_intent->>'medioPagoId')::uuid)::text IS DISTINCT FROM p_intent->>'medioPagoId' OR (p_intent->>'compradorId' IS NOT NULL AND ((p_intent->>'compradorId')::uuid)::text IS DISTINCT FROM p_intent->>'compradorId') THEN RAISE EXCEPTION 'Canonical sale catalog IDs required';END IF;
  heads=(p_intent->>'cabezas')::integer;IF heads<1 OR to_jsonb(heads) IS DISTINCT FROM p_intent->'cabezas' OR(jsonb_array_length(p_intent->'animals')<>0 AND jsonb_array_length(p_intent->'animals')<>heads) THEN RAISE EXCEPTION 'Exact sale heads/link count required';END IF;
  day=(p_intent->>'fecha')::date;IF NOT isfinite(day) OR to_char(day,'YYYY-MM-DD') IS DISTINCT FROM p_intent->>'fecha' OR day>(now() AT TIME ZONE 'America/Bogota')::date THEN RAISE EXCEPTION 'Canonical actual sale date required';END IF;
  IF(SELECT coalesce(jsonb_agg(x ORDER BY x->>'id'),'[]') FROM jsonb_array_elements(p_intent->'animals')x) IS DISTINCT FROM p_intent->'animals' OR(SELECT count(DISTINCT x->>'id') FROM jsonb_array_elements(p_intent->'animals')x)<>jsonb_array_length(p_intent->'animals') THEN RAISE EXCEPTION 'Sorted unique sale animals required';END IF;
  IF r.request_key IS NOT NULL THEN IF r.intent IS NOT NULL AND r.intent IS DISTINCT FROM p_intent THEN RAISE EXCEPTION 'Original sale intent changed';END IF;RETURN hato_sale.result(r);END IF;
  original=hato_sale.snapshot(p_intent);
  IF (SELECT coalesce(jsonb_agg(jsonb_build_object('id',x->'animal'->'id','numero',x->'animal'->'numero','nombre',x->'animal'->'nombre') ORDER BY x->'animal'->>'id'),'[]') FROM jsonb_array_elements(original->'animals')x) IS DISTINCT FROM p_intent->'animals' OR EXISTS(SELECT 1 FROM jsonb_array_elements(original->'animals')x WHERE x->'animal'->>'estado' IS DISTINCT FROM 'activa') THEN RAISE EXCEPTION 'Observed active sale animals changed';END IF;
  IF p_intent->'refs' IS DISTINCT FROM jsonb_build_object('region',jsonb_build_object('id',original->'refs'->'region'->'id','nombre',original->'refs'->'region'->'nombre'),'medio',jsonb_build_object('id',original->'refs'->'medio'->'id','nombre',original->'refs'->'medio'->'nombre'),'comprador',CASE WHEN p_intent->>'compradorId' IS NULL THEN NULL ELSE jsonb_build_object('id',original->'refs'->'comprador'->'id','nombre',original->'refs'->'comprador'->'nombre') END) THEN RAISE EXCEPTION 'Observed sale catalog identity changed';END IF;
  r.request_key=p_request_key;r.owner_id=p_expected_owner;r.intent=p_intent;r.original=original;r.plan=jsonb_build_object('incomeId',gen_random_uuid(),'events',(SELECT coalesce(jsonb_agg(jsonb_build_object('animalId',x->>'id','eventId',gen_random_uuid()) ORDER BY x->>'id'),'[]') FROM jsonb_array_elements(p_intent->'animals')x));r.state='pending';expected=r;INSERT INTO hato_sale.requests SELECT expected.* RETURNING * INTO r;IF NOT FOUND OR to_jsonb(r) IS DISTINCT FROM to_jsonb(expected) THEN RAISE EXCEPTION 'Sale reservation suppressed/mutated';END IF;
 ELSIF p_action='resolve' THEN
  IF r.request_key IS NULL THEN r.request_key=p_request_key;r.owner_id=p_expected_owner;r.state='canceled';expected=r;INSERT INTO hato_sale.requests SELECT expected.* RETURNING * INTO r;
  ELSIF r.state='pending' THEN expected=r;expected.state='canceled';UPDATE hato_sale.requests SET state='canceled' WHERE request_key=p_request_key RETURNING * INTO r;ELSE RETURN hato_sale.result(r);END IF;
  IF NOT FOUND OR to_jsonb(r) IS DISTINCT FROM to_jsonb(expected) THEN RAISE EXCEPTION 'Sale cancellation suppressed/mutated';END IF;
 ELSE
  IF r.request_key IS NULL THEN RAISE EXCEPTION 'Original prepared sale required';END IF;IF r.state='committed' THEN IF NOT EXISTS(SELECT 1 FROM hato_sale.audit WHERE request_key=p_request_key AND receipt=r.receipt) THEN RAISE EXCEPTION 'Original sale audit missing';END IF;RETURN hato_sale.result(r);ELSIF r.state<>'pending' THEN RAISE EXCEPTION 'Canceled sale cannot post';END IF;
  original=r.original;IF hato_sale.snapshot(r.intent) IS DISTINCT FROM original THEN RAISE EXCEPTION 'Original sale source graph changed';END IF;day=(r.intent->>'fecha')::date;heads=(r.intent->>'cabezas')::integer;amount=(r.intent->>'valor')::numeric;
  income=jsonb_populate_record(NULL::public.fin_ingresos,jsonb_build_object('id',r.plan->>'incomeId','fecha',day,'negocio_id',original->'refs'->'negocio'->>'id','categoria_id',original->'refs'->'categoria'->>'id','region_id',r.intent->>'regionId','medio_pago_id',r.intent->>'medioPagoId','comprador_id',r.intent->>'compradorId','nombre',CASE WHEN r.intent->>'nombre'='' THEN 'Venta '||(r.intent->>'tipo')||' ('||heads::text||' cabezas)' ELSE r.intent->>'nombre' END,'valor',amount,'cabezas',heads,'created_by',p_expected_owner,'created_at',now(),'updated_at',now()));
  INSERT INTO public.fin_ingresos SELECT income.* RETURNING * INTO actual_income;IF NOT FOUND OR to_jsonb(actual_income) IS DISTINCT FROM to_jsonb(income) THEN RAISE EXCEPTION 'Sale income suppressed/mutated';END IF;
  corrections=before_source->'domain'->'corrections';
  FOR g IN SELECT x FROM jsonb_array_elements(original->'animals')x LOOP
   SELECT x INTO item FROM jsonb_array_elements(r.plan->'events')x WHERE x->>'animalId'=g->'animal'->>'id';
   e=jsonb_populate_record(NULL::public.hato_eventos,jsonb_build_object('id',item->>'eventId','animal_id',item->>'animalId','tipo','venta','fecha',day,'fecha_confianza','exacta','fin_ingreso_id',income.id,'fuente','web','datos',jsonb_build_object('tipo_venta',r.intent->>'tipo','cabezas_transaccion',heads,'valor_transaccion',amount),'created_by',p_expected_owner,'created_at',now()));
   INSERT INTO public.hato_eventos SELECT e.* RETURNING * INTO actual_event;IF NOT FOUND OR to_jsonb(actual_event) IS DISTINCT FROM to_jsonb(e) THEN RAISE EXCEPTION 'Sale event suppressed/mutated';END IF;
   a=jsonb_populate_record(NULL::public.hato_animales,g->'animal');a.estado='vendida';a.fecha_estado=day;UPDATE public.hato_animales SET estado=a.estado,fecha_estado=a.fecha_estado WHERE id=a.id RETURNING * INTO actual_animal;IF NOT FOUND OR to_jsonb(actual_animal) IS DISTINCT FROM to_jsonb(a) THEN RAISE EXCEPTION 'Sale animal suppressed/mutated';END IF;
   SELECT * INTO correction FROM public.hato_correcciones WHERE id NOT IN(SELECT(x->>'id')::uuid FROM jsonb_array_elements(corrections||new_corrections)x) AND fila_id=a.id;
   IF NOT FOUND OR correction.tabla<>'hato_animales' OR correction.operacion<>'update' OR correction.datos_anteriores IS DISTINCT FROM g->'animal' OR correction.datos_nuevos IS DISTINCT FROM to_jsonb(a) OR correction.animal_id<>a.id OR correction.corregido_por IS DISTINCT FROM p_expected_owner OR correction.corregido_en IS DISTINCT FROM now() OR correction.motivo IS NOT NULL THEN RAISE EXCEPTION 'Exact trusted sale correction required';END IF;
   new_corrections=new_corrections||jsonb_build_array(to_jsonb(correction));
   targets=targets||jsonb_build_array(jsonb_set(jsonb_set(g,'{animal}',to_jsonb(a)),'{events}',(SELECT jsonb_agg(x ORDER BY x->>'id') FROM jsonb_array_elements((g->'events')||jsonb_build_array(to_jsonb(e)))x)));
   expected_source=jsonb_set(expected_source,'{domain,animals}',(SELECT jsonb_agg(CASE WHEN x->>'id'=a.id::text THEN to_jsonb(a) ELSE x END ORDER BY x->>'id') FROM jsonb_array_elements(expected_source->'domain'->'animals')x));
   expected_source=jsonb_set(expected_source,'{domain,events}',(SELECT jsonb_agg(x ORDER BY x->>'id') FROM jsonb_array_elements((expected_source->'domain'->'events')||jsonb_build_array(to_jsonb(e)))x));
  END LOOP;
  expected_source=jsonb_set(expected_source,'{domain,corrections}',(SELECT coalesce(jsonb_agg(x ORDER BY x->>'id'),'[]') FROM jsonb_array_elements(corrections||new_corrections)x));
  expected_source=jsonb_set(expected_source,'{animalsView}',(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY animal_id),'[]') FROM public.v_hato_estado_actual x));
  expected_finance=jsonb_set(expected_finance,ARRAY['public.fin_ingresos'],(SELECT jsonb_agg(x ORDER BY x::text) FROM jsonb_array_elements((before_finance->'public.fin_ingresos')||jsonb_build_array(to_jsonb(income)))x));
  after_value=hato_sale.snapshot(r.intent);expected_after=jsonb_set(original,'{animals}',targets);IF after_value IS DISTINCT FROM expected_after THEN RAISE EXCEPTION 'Sale exact final target mismatch';END IF;
  new_receipt=jsonb_build_object('version',1,'requestKey',p_request_key,'owner',p_expected_owner,'intent',r.intent,'original',original,'plan',r.plan,'actor',actor,'recordedAt',now(),'income',to_jsonb(income),'after',after_value,'corrections',new_corrections);
  INSERT INTO hato_sale.audit VALUES(p_request_key,new_receipt) RETURNING receipt INTO written_audit;IF NOT FOUND OR written_audit IS DISTINCT FROM new_receipt THEN RAISE EXCEPTION 'Sale audit suppressed/mutated';END IF;
  expected=r;expected.state='committed';expected.receipt=new_receipt;UPDATE hato_sale.requests SET state='committed',receipt=new_receipt WHERE request_key=p_request_key RETURNING * INTO r;IF NOT FOUND OR to_jsonb(r) IS DISTINCT FROM to_jsonb(expected) THEN RAISE EXCEPTION 'Sale committed control suppressed/mutated';END IF;
 END IF;
 IF hato_sale.actor() IS DISTINCT FROM actor OR alert_cron.source() IS DISTINCT FROM expected_source OR hato_sale.finance() IS DISTINCT FROM expected_finance OR view_inputs IS DISTINCT FROM jsonb_build_object('checks',(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY id),'[]') FROM public.hato_chequeo_vacas x),'headers',(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY id),'[]') FROM public.hato_chequeos x)) THEN RAISE EXCEPTION 'Sale final authority/source/financial mismatch';END IF;
 SELECT * INTO r FROM hato_sale.requests WHERE request_key=p_request_key;IF NOT FOUND OR to_jsonb(r) IS DISTINCT FROM to_jsonb(expected) THEN RAISE EXCEPTION 'Sale final control readback mismatch';END IF;
 IF r.state='committed' AND(hato_sale.snapshot(r.intent) IS DISTINCT FROM r.receipt->'after' OR NOT EXISTS(SELECT 1 FROM hato_sale.audit WHERE request_key=p_request_key AND receipt=r.receipt) OR(SELECT to_jsonb(x) FROM public.fin_ingresos x WHERE id=(r.plan->>'incomeId')::uuid) IS DISTINCT FROM r.receipt->'income') THEN RAISE EXCEPTION 'Sale final audit/target/income readback mismatch';END IF;
 RETURN hato_sale.result(r);
END $$;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA hato_sale FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.fn_hato_sale_web(text,uuid,jsonb,uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.fn_hato_sale_web(text,uuid,jsonb,uuid) TO authenticated;
COMMIT;
